// BUILD WORD FILE (.docx)
// Builds a real Word document from my CV + the tailored text saved for this job.
// A .docx file is a zip of XML files; this code writes the XML and the zip itself
// (no external libraries needed).
const job = $input.first().json;
const type = String($("Download Link Clicked").first().json.query?.type || "cv").toLowerCase();

const ME = {
  name: "YOUR NAME",
  title: "AI Engineer Intern | Machine Learning | LLMs & Agentic AI | AI Automation",
  contact: "Your City, UK | +44 0000 000000 | you@example.com | linkedin.com/in/your-profile | github.com/your-username",
  summary: "Computer Science graduate and MSc Artificial Intelligence student at Teesside University who builds practical, explainable LLM applications.",
  skills: [
    ["Programming Languages", "Python, JavaScript, Java, SQL, C, C++"],
    ["LLMs & Agentic AI", "Large Language Models (LLMs), Generative AI, LangChain, LangGraph, Groq API, Prompt Engineering, Context Engineering, Structured Outputs (JSON Schema), LLM Output Verification"],
    ["AI Workflow Automation", "n8n (Webhooks, Form Trigger, Schedule Trigger, HTTP Request, Code nodes, Data Tables), API integration, error handling and retries"],
    ["AI & Machine Learning", "Machine Learning, Deep Learning, Neural Networks, CNNs, Computer Vision, Model Training and Evaluation, TensorFlow, PyTorch, Scikit-learn, OpenCV, YOLO, Faster R-CNN"],
    ["Responsible AI", "PII anonymisation, human-in-the-loop design, data minimisation (UK GDPR principles)"],
    ["Data & Analytics", "Pandas, NumPy, Data Cleaning, Data Preprocessing, Exploratory Data Analysis"],
    ["Web Development & APIs", "REST APIs, JSON, Flask, Node.js, Express.js, React.js, HTML, CSS, Spring Boot"],
    ["Databases", "MySQL, SQL, MongoDB"],
    ["Developer Tools", "Git, GitHub, Docker, VS Code, Jupyter Notebook, Postman"]
  ],
  projects: [
    { name: "AI Job Hunt Agent", tech: "n8n, Groq API, Reed Jobs API, Remotive API, JavaScript, n8n Data Tables, Docker", bullets: [
      "Built a scheduled n8n agent that runs 9 searches across the Reed and Remotive job APIs every morning and collects graduate, junior, internship and part-time roles in AI, data and IT.",
      "Wrote JavaScript to merge both APIs into one format, remove senior roles, old and unrelated ads, keep only UK-eligible remote jobs, and remove duplicates.",
      "An LLM rates each job requirement with an exact CV quote; code verifies every quote and calculates the match score, with warning flags for paid training schemes.",
      "Generates tailored CVs, cover letters and interview prep, with a chat agent, run log and error alerts."] },
    { name: "AI CV Screening Assistant", tech: "n8n, Groq API (gpt-oss-20b), JavaScript, Webhooks, REST APIs, n8n Data Tables, HTML/CSS, Docker", bullets: [
      "Built an n8n workflow that screens a CV against a job description and returns an evidence-based report, through an animated web form and a JSON webhook API.",
      "Moved scoring out of the LLM: the model rates each requirement and JavaScript calculates a 0-100 score from a weighted rubric (required 50%, preferred 20%, experience 20%, education 10%).",
      "Added a hallucination check that searches the CV for every AI evidence quote; unverified quotes get half credit and are flagged for the human reviewer.",
      "Used strict JSON-schema output, temperature 0 and a fixed seed; the same CV scored 82/100 in 3 repeated runs."] }
  ],
  education: [
    ["MSc Artificial Intelligence – Teesside University, United Kingdom", "January 2026 – January 2028 (expected)", "Machine Learning, Deep Learning, Computer Vision, Natural Language Processing, Intelligent Systems and AI Applications."],
    ["B.Tech Computer Science and Engineering – Christu Jyothi Institute of Technology and Science, India", "October 2021 – July 2025", "Programming, Data Structures and Algorithms, Object-Oriented Programming, Database Management Systems and Software Engineering."]
  ],
  extra: ["Availability: [your availability].", "References available upon request."]
};

// --- read the tailored text saved by the job agent ---
const t = String(job.tailored_cv || "");
const section = (start, end) => {
  const i = t.indexOf(start); if (i < 0) return "";
  const rest = t.slice(i + start.length);
  const j = end ? rest.indexOf(end) : -1;
  return (j >= 0 ? rest.slice(0, j) : rest).trim();
};
const tSummary = section("PROFESSIONAL SUMMARY (tailored)", "KEY SKILLS");
const tSkills = section("KEY SKILLS (put these first)", "PROJECT BULLETS");
const tBullets = section("PROJECT BULLETS TO USE", "ATS KEYWORDS").split("\n").map((l) => l.replace(/^[-•]\s*/, "").trim()).filter(Boolean);

// --- Word XML helpers ---
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const run = (text, o = {}) => `<w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/>${o.b ? "<w:b/>" : ""}${o.i ? "<w:i/>" : ""}<w:sz w:val="${o.sz || 20}"/>${o.color ? `<w:color w:val="${o.color}"/>` : ""}</w:rPr><w:t xml:space="preserve">${esc(text)}</w:t></w:r>`;
const para = (runs, o = {}) => `<w:p><w:pPr>${o.center ? '<w:jc w:val="center"/>' : ""}<w:spacing w:before="${o.before || 0}" w:after="${o.after ?? 60}"/>${o.indent ? '<w:ind w:left="360" w:hanging="220"/>' : ""}${o.rule ? '<w:pBdr><w:bottom w:val="single" w:sz="6" w:space="1" w:color="1F3A5F"/></w:pBdr>' : ""}</w:pPr>${runs}</w:p>`;
const heading = (text) => para(run(text.toUpperCase(), { b: true, sz: 22, color: "1F3A5F" }), { before: 200, after: 80, rule: true });
const bullet = (text) => para(run("•  ") + run(text), { indent: true, after: 40 });

let body = "";
let fileName;
if (type === "letter") {
  const today = new Date().toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric", timeZone: "Europe/London" });
  body += para(run("Your Name", { b: true, sz: 24 }), { after: 20 });
  body += para(run(ME.contact, { sz: 18 }), { after: 240 });
  body += para(run(today), { after: 240 });
  body += para(run("Re: " + job.title + " – " + job.company, { b: true }), { after: 200 });
  String(job.cover_letter || "").split(/\n+/).forEach((line) => { if (line.trim()) body += para(run(line.trim(), { sz: 21 }), { after: 160 }); });
  fileName = "Cover Letter - Your Name - " + job.company;
} else {
  body += para(run(ME.name, { b: true, sz: 32, color: "1F3A5F" }), { center: true, after: 20 });
  body += para(run(ME.title, { sz: 20 }), { center: true, after: 20 });
  body += para(run(ME.contact, { sz: 17 }), { center: true, after: 120 });
  body += heading("Professional Summary");
  body += para(run(tSummary || ME.summary, { sz: 20 }));
  if (tSkills) { body += heading("Key Skills for this Role"); body += para(run(tSkills.replace(/ · /g, " | "), { sz: 20 })); }
  if (tBullets.length) { body += heading("Relevant Highlights"); tBullets.forEach((b) => (body += bullet(b))); }
  body += heading("Technical Skills");
  ME.skills.forEach(([k, v]) => (body += para(run(k + ": ", { b: true }) + run(v), { after: 40 })));
  body += heading("Projects");
  ME.projects.forEach((p) => {
    body += para(run(p.name, { b: true, sz: 21 }), { before: 80, after: 20 });
    body += para(run("Technologies: " + p.tech, { i: true, sz: 18 }), { after: 40 });
    p.bullets.forEach((b) => (body += bullet(b)));
  });
  body += heading("Education");
  ME.education.forEach(([d, when, areas]) => {
    body += para(run(d, { b: true }), { before: 60, after: 20 });
    body += para(run(when, { i: true, sz: 18 }), { after: 20 });
    body += para(run("Relevant areas: " + areas, { sz: 19 }), { after: 60 });
  });
  body += heading("Additional Information");
  ME.extra.forEach((x) => (body += bullet(x)));
  fileName = "CV - Your Name - " + job.company;
}
fileName = fileName.replace(/[^\w\s.-]/g, "").replace(/\s+/g, " ").trim() + ".docx";

const docXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${body}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="850" w:right="900" w:bottom="850" w:left="900" w:header="0" w:footer="0" w:gutter="0"/></w:sectPr></w:body></w:document>`;
const files = {
  "[Content_Types].xml": `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>`,
  "_rels/.rels": `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`,
  "word/document.xml": docXml
};

// --- tiny zip writer (stored, no compression) ---
const crcTable = Array.from({ length: 256 }, (_, n) => { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; return c >>> 0; });
const crc32 = (bytes) => { let c = 0xffffffff; for (const b of bytes) c = crcTable[(c ^ b) & 0xff] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
const enc = new TextEncoder();
const chunks = [], central = [];
let offset = 0;
const u16 = (v) => [v & 0xff, (v >>> 8) & 0xff];
const u32 = (v) => [v & 0xff, (v >>> 8) & 0xff, (v >>> 16) & 0xff, (v >>> 24) & 0xff];
for (const [name, content] of Object.entries(files)) {
  const nameB = enc.encode(name), data = enc.encode(content), crc = crc32(data);
  const local = [...u32(0x04034b50), ...u16(20), ...u16(0), ...u16(0), ...u16(0), ...u16(0x21), ...u32(crc), ...u32(data.length), ...u32(data.length), ...u16(nameB.length), ...u16(0)];
  chunks.push(Uint8Array.from(local), nameB, data);
  central.push(Uint8Array.from([...u32(0x02014b50), ...u16(20), ...u16(20), ...u16(0), ...u16(0), ...u16(0), ...u16(0x21), ...u32(crc), ...u32(data.length), ...u32(data.length), ...u16(nameB.length), ...u16(0), ...u16(0), ...u16(0), ...u16(0), ...u32(0), ...u32(offset)]), nameB);
  offset += local.length + nameB.length + data.length;
}
const cdSize = central.reduce((s, c) => s + c.length, 0);
const end = Uint8Array.from([...u32(0x06054b50), ...u16(0), ...u16(0), ...u16(3), ...u16(3), ...u32(cdSize), ...u32(offset), ...u16(0)]);
const all = [...chunks, ...central, end];
const total = all.reduce((s, c) => s + c.length, 0);
const zip = new Uint8Array(total);
let pos = 0; for (const c of all) { zip.set(c, pos); pos += c.length; }

return [{
  json: { fileName },
  binary: { data: { data: Buffer.from(zip).toString("base64"), mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document", fileName, fileExtension: "docx" } }
}];
